insert into public.training_sources(source_key,authority,title,source_type,canonical_url,publication_date,checked_on,license_kind,reuse_policy,normative_status,topics,notes,metadata)
values
('gu-dm388-2003','Ministero della Salute - Gazzetta Ufficiale','D.M. 15 luglio 2003, n. 388 - pronto soccorso aziendale','normative_source','https://www.gazzettaufficiale.it/atto/vediMenuHTML?atto.codiceRedazionale=004G0046&atto.dataPubblicazioneGazzetta=2004-02-03&tipoSerie=serie_generale&tipoVigenza=originario',date '2003-07-15',date '2026-10-15','official_public_source','quote_minimally_and_reference','primary',array['primo soccorso','DM 388/2003','formazione addetti','gruppo A','gruppi B/C'],'Fonte normativa primaria per organizzazione e contenuti minimi della formazione degli addetti al primo soccorso.',jsonb_build_object('priority','primary_normative')),
('inail-primo-soccorso-2018','INAIL','Il primo soccorso nei luoghi di lavoro','technical_manual','https://www.inail.it/portale/it/inail-comunica/news/notizia.2018.10.primo-soccorso-nei-luoghi-di-lavoro-online-un-nuovo-manuale-inail.html',date '2018-10-04',date '2026-10-15','institutional_terms','reference_and_original_rewrite','supporting',array['primo soccorso','organizzazione','emergenza sanitaria','addetti'],'Manuale tecnico-didattico INAIL per organizzazione e principi del primo soccorso aziendale; contenuti SafetyTraining riscritti e verificati.',jsonb_build_object('priority','technical_reference')),
('inail-dae-2025','INAIL','La diffusione e l’utilizzo dei defibrillatori (DAE) nei luoghi di lavoro','technical_brief','https://www.inail.it/content/dam/inail-hub-site/documenti/catalogo-generale/2025/06/Diffusione%20e%20utilizzo%20Defibrillatori.pdf',date '2025-01-01',date '2026-10-15','citation_only','citation_only_reference','supporting',array['DAE','arresto cardiaco','RCP','primo soccorso','luoghi di lavoro'],'Pubblicazione INAIL 2025: consentita la sola citazione con indicazione della fonte; non copiare testo o grafica. Usare soltanto fatti e riferimenti tecnici per contenuti originali.',jsonb_build_object('priority','high_evidence','copyright_note','citation only; no reproduction'))
