with base as (
 select lu.id learning_unit_id,lu.stable_key,v.content
 from public.learning_units lu
 join lateral (select content from public.learning_unit_versions luv where luv.learning_unit_id=lu.id and luv.status='published' order by version_number desc limit 1) v on true
 where lu.stable_key in ('primo_soccorso:allertamento-sicurezza-scena','primo_soccorso:valutazione-iniziale','primo_soccorso:funzioni-vitali','primo_soccorso:traumi-emorragie')
), enriched as (
 select learning_unit_id,stable_key,
  content || jsonb_build_object(
    'didactic_version','first-aid-v2',
    'quality',coalesce(content->'quality','{}'::jsonb) || jsonb_build_object('teacher_ready',true,'learner_ready',true,'scenario_based',true,'practical_transfer_required',true),
    'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-15','reuse_policy','reference_and_original_rewrite','normative_validation','D.M. 388/2003'),
    'evidence_sources',jsonb_build_array(
      jsonb_build_object('authority','Ministero della Salute - Gazzetta Ufficiale','title','D.M. 15 luglio 2003, n. 388','url','https://www.gazzettaufficiale.it/atto/vediMenuHTML?atto.codiceRedazionale=004G0046&atto.dataPubblicazioneGazzetta=2004-02-03&tipoSerie=serie_generale&tipoVigenza=originario','use','normative_validation','checked_on','2026-10-15'),
      jsonb_build_object('authority','INAIL','title','Il primo soccorso nei luoghi di lavoro','url','https://www.inail.it/portale/it/inail-comunica/news/notizia.2018.10.primo-soccorso-nei-luoghi-di-lavoro-online-un-nuovo-manuale-inail.html','use','technical_didactic_reference','checked_on','2026-10-15')
    ) || case when stable_key='primo_soccorso:funzioni-vitali' then jsonb_build_array(jsonb_build_object('authority','INAIL','title','La diffusione e l’utilizzo dei defibrillatori (DAE) nei luoghi di lavoro','url','https://www.inail.it/content/dam/inail-hub-site/documenti/catalogo-generale/2025/06/Diffusione%20e%20utilizzo%20Defibrillatori.pdf','use','technical_reference_citation_only','checked_on','2026-10-15')) else '[]'::jsonb end,
    'delivery_note','Il contenuto digitale supporta comprensione, decisione e preparazione; non sostituisce esercitazioni pratiche e verifica delle capacità previste dal percorso di primo soccorso.'
  ) || case stable_key
   when 'primo_soccorso:allertamento-sicurezza-scena' then jsonb_build_object(
     'scene_safety_lab',jsonb_build_object('title','Prima di toccare: rendi possibile il soccorso senza creare un secondo infortunato','scan',jsonb_build_array('energia/macchine in movimento','elettricità','traffico/mezzi','incendio/fumo/gas','agenti chimici o biologici','strutture instabili/caduta oggetti','violenza o altra minaccia','necessità di DPI/barriere'),'decision',jsonb_build_array('scena sicura: avvicinati secondo addestramento','scena rendibile sicura solo da soggetto competente: allerta e impedisci accessi','scena non sicura: non entrare; attiva soccorsi e supporto tecnico'),'scenario','Persona a terra accanto a macchina non chiaramente isolata: il corsista deve impedire l’accesso, attivare chi può mettere in sicurezza, chiamare i soccorsi e preparare l’accesso.','teacher_questions',jsonb_build_array('Qual è il pericolo per il soccorritore?','Chi ha il potere/competenza di eliminarlo?','Che cosa puoi fare senza entrare nella zona?','Quale informazione deve ricevere subito la centrale?')),
     'emergency_call_handover',jsonb_build_object('fields',jsonb_build_array('dove: sede/indirizzo/punto di accesso','che cosa è successo','quante persone sono coinvolte','condizioni osservabili essenziali','pericoli ancora presenti','numero/recapito del chiamante','chi guiderà i soccorsi all’evento'),'rule','Descrivere fatti osservabili e rispondere alle domande dell’operatore; non ritardare la chiamata per formulare una diagnosi.')
   )
   when 'primo_soccorso:valutazione-iniziale' then jsonb_build_object(
     'initial_assessment_lab',jsonb_build_object('title','Riconosci ciò che cambia la priorità','observe',jsonb_build_array('risposta alla voce/stimolo previsto dall’addestramento','respirazione normale o non normale','emorragia importante evidente','meccanismo/evento potenzialmente grave','segni osservabili di rapido peggioramento'),'decision_cards',jsonb_build_array('non risponde/non respira normalmente → emergenza immediata e sequenza pratica appresa','respira ma non risponde → protezione, soccorso urgente, assistenza secondo addestramento','risponde ma presenta segni importanti → attivazione precoce e monitoraggio','condizione apparentemente minore → assistenza entro competenze e rivalutazione'),'anti_diagnosis_rule','L’addetto descrive segni, sintomi riferiti, dinamica e cambiamenti; non deve stabilire diagnosi mediche.','microexercise','Il docente mostra cinque mini-scenari da 30 secondi: il corsista deve dire cosa osserva, quando chiama e quale informazione passa.'),
     'reassessment_loop',jsonb_build_array('osserva','agisci/chiedi aiuto','rivaluta','riferisci ogni cambiamento ai soccorsi')
   )
   when 'primo_soccorso:funzioni-vitali' then jsonb_build_object(
     'cardiac_arrest_skill_bridge',jsonb_build_object('title','Riconosci – allerta – agisci – usa il DAE secondo formazione e istruzioni','sequence',jsonb_build_array('conferma che la scena sia sicura','riconosci mancata risposta e respirazione non normale secondo addestramento','attiva immediatamente 112/118 e organizza l’arrivo dei soccorsi','avvia la sequenza di rianimazione appresa su manichino','recupera/usa il DAE quando disponibile seguendo formazione e istruzioni vocali','durante analisi o eventuale scarica assicurati che nessuno tocchi la persona','prosegui secondo protocollo/addestramento fino al subentro dei soccorsi o cambiamento della condizione'),'skill_check',jsonb_build_array('sicurezza e riconoscimento','allertamento senza ritardo','organizzazione dei compiti','qualità della sequenza su manichino valutata dall’istruttore','sicurezza durante uso DAE','continuità e comunicazione'),'teacher_rule','Le abilità RCP/DAE vanno dimostrate, esercitate e corrette in presenza con attrezzatura didattica; la LU digitale non certifica la competenza manuale.'),
     'dae_source_note','INAIL 2025 richiama allertamento precoce, rianimazione e defibrillazione; la fonte è usata solo come riferimento tecnico/citazione, senza riprodurre grafica o testo.'
   )
   when 'primo_soccorso:traumi-emorragie' then jsonb_build_object(
     'bleeding_trauma_lab',jsonb_build_object('title','Proteggi, riconosci la gravità, controlla ciò che sai controllare, non aggravare','sequence',jsonb_build_array('proteggiti dal contatto con sangue/fluidi','individua emorragia importante o dinamica traumatica significativa','attiva precocemente i soccorsi quando indicato','applica soltanto tecniche e presidi di controllo dell’emorragia insegnati nel corso','non rimuovere oggetti conficcati e non eseguire riallineamenti improvvisati','evita movimenti non necessari dopo trauma importante','mantieni osservazione e riferisci peggioramenti'),'scenario','Caduta con ferita sanguinante e dolore al collo: il gruppo deve organizzare DPI, chiamata, controllo iniziale del sanguinamento, protezione dai movimenti e passaggio di consegne.','common_error_drill',jsonb_build_array('toccare sangue senza barriera','far alzare la persona per verificare se riesce a camminare','rimuovere un corpo estraneo conficcato','ritardare il soccorso perché la persona è cosciente','somministrare cibo, bevande o farmaci senza indicazione sanitaria')),
     'handover_after_trauma',jsonb_build_array('dinamica/evento','ora approssimativa','segni osservati','cambiamenti nel tempo','azioni effettuate','presidi utilizzati','pericoli/esposizioni pertinenti')
   ) end as new_content
 from base
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at)
select learning_unit_id,2,'draft',new_content,md5(new_content::text),null from enriched
on conflict (learning_unit_id,version_number) do update set status='draft',content=excluded.content,content_hash=excluded.content_hash,published_at=null;

